add_block('simulink/Dashboard/Knob', [mdl '/Knob']);
p = Simulink.HMI.ParamSourceInfo;
p.BlockPath = Simulink.BlockPath([mdl '/Gain']);
p.ParamName = 'Gain';
set_param([mdl '/Knob'], 'Binding', p, 'Limits', [0 1 10]);

add_block('simulink/Dashboard/Slider', [mdl '/Freq']);
p = Simulink.HMI.ParamSourceInfo;
p.BlockPath = Simulink.BlockPath([mdl '/Sine Wave']);
p.ParamName = 'Frequency';
set_param([mdl '/Freq'], 'Binding', p);

add_block('simulink/Dashboard/Toggle Switch', [mdl '/Dir']);
st = struct('Value', {-5, 5}, 'Label', {'Reverse', 'Forward'})';
set_param([mdl '/Dir'], 'States', st);

add_block('simulink/Dashboard/Rotary Switch', [mdl '/Sel']);
st = struct('Value', {1, 2, 3}, 'Label', {'Low', 'Mid', 'High'})';
set_param([mdl '/Sel'], 'States', st);

add_block('simulink/Dashboard/Combo Box', [mdl '/Profile']);
st = struct('Value', {1, 2, 3}, 'Label', {'Urban', 'Highway', 'Mixed'})';
set_param([mdl '/Profile'], 'States', st);

add_block('simulink/Dashboard/Gauge', [mdl '/Speed']);
s = Simulink.HMI.SignalSpecification;
s.BlockPath = Simulink.BlockPath([mdl '/Vehicle']);
s.OutputPortIndex = 1;
set_param([mdl '/Speed'], 'Binding', s);

add_block('simulink/Messages & Events/Send', [mdl '/Send']);
add_block('simulink/Messages & Events/Queue', [mdl '/Q']);
add_block('simulink/Messages & Events/Receive', [mdl '/Recv']);
add_line(mdl, 'Send/1', 'Q/1'); add_line(mdl, 'Q/1', 'Recv/1');

add_block('simulink/Messages & Events/Message Merge', [mdl '/MM']);
set_param([mdl '/MM'], 'NumberInputPorts', '3');
add_line(mdl, 'SendA/1', 'MM/1'); add_line(mdl, 'SendB/1', 'MM/2');
